// Robust JSON extractor for AI responses (handles ```json fenced blocks)
const raw = $json?.choices?.[0]?.message?.content ?? $json?.message?.content ?? "";

if(!raw || raw.trim().length === 0) {
  throw new Error("No AI output found in the response.");
}

let text = String(raw).trim();

// remove common fences like ```json or ``` ... ```
text = text.replace(/^\s*```(?:json)?\s*/i, "");
text = text.replace(/\s*```\s*$/i, "");

// sometimes models prepend text; find the first { and the last }
const firstBrace = text.indexOf("{");
const lastBrace = text.lastIndexOf("}");

if(firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
  throw new Error("Could not find a JSON object inside AI output. Raw output:\n" + raw);
}

const candidate = text.slice(firstBrace, lastBrace + 1);

// try parse
let parsed;
try {
  parsed = JSON.parse(candidate);
} catch (err) {
  // include short raw snippet for debugging
  throw new Error("Failed to parse JSON from AI output. Extracted text:\n" + candidate + "\n\nParse error: " + err.message);
}

// Return parsed JSON (so next nodes receive heading/post keys)
return [{ json: parsed }];

function getVal(obj, keys) {
  for (const k of keys) {
    if (obj && obj[k] !== undefined && obj[k] !== null) {
      return String(obj[k]);
    }
  }
  return "";
}

// 🔥 SAFE trigger read
const trg = $input.first()?.json || {};

const topic = getVal(trg, ["topic_heading","  topic_heading  "]).trim().toLowerCase();
const desc = getVal(trg, ["user_description","  user_description  "]).trim().toLowerCase();
const postedOnMon = getVal(trg, ["posted_on_monday","  posted_on_monday  "]).trim().toLowerCase();

if (!topic && !desc && !postedOnMon) {
  throw new Error("Trigger item is empty. Run workflow from trigger, not this node.");
}

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;

  const rTopic = getVal(row, ["topic_heading","  topic_heading  "]).trim().toLowerCase();
  const rDesc = getVal(row, ["user_description","  user_description  "]).trim().toLowerCase();
  const rPosted = getVal(row, ["posted_on_monday","  posted_on_monday  "]).trim().toLowerCase();

  if (
    topic === rTopic &&
    postedOnMon === rPosted &&
    (desc === "" || desc === rDesc)
  ) {
    return [{ json: { rowIndex: i + 1, rowData: row } }];
  }
}

throw new Error(
  "No row match. Trigger values: " +
  JSON.stringify({ topic, desc, postedOnMon })
);

// merged item comes as items[0]
const item = items[0].json;

// rowData contains form data
const row = item.rowData;

// return final clean structure
return [
  {
    json: {
      posted: false,
      approval_status: "pending",

      ai_post: item.ai_post,
      ai_heading: item.ai_heading,
      post_id: item.post_id,

      // form fields
      "  posted_on_monday  ": row["  posted_on_monday  "],
      "  topic_heading  ": row["  topic_heading  "],
      "  need_headings  ": row["  need_headings  "],
      "  need_emojis  ": row["  need_emojis  "],
      "  user_description  ": row["  user_description  "],

      row_number: row.row_number
    }
  }
];

return [
  {
    json: {
      approval: String($input.first().json["Do you approve this X post?"])
        .trim()
        .toLowerCase(),
      improvement:
        $json["Please mention what needs to be improved."] || "",
      post_id: $json["post_id"] || ""
    }
  }
];

const pid = $json.post_id;

for (const item of items) {
  if (item.json.post_id === pid) {
    return [{
      json: {
        post_id: pid,
        previous_heading: item.json.ai_heading,
        previous_post: item.json.ai_post,
        improvement: $node["Code in JavaScript4"].json.improvement
      }
    }];
  }
}

throw new Error("Post ID not found: " + pid);

